pub struct Solution;

impl Solution {
    pub fn is_match(s: String, p: String) -> bool {
        let s_bytes = s.as_bytes();
        let p_bytes = p.as_bytes();
        let mut s_idx = 0;
        let mut p_idx = 0;
        let mut star_idx: Option<usize> = None;
        let mut s_temp = 0;

        while s_idx < s_bytes.len() {
            if p_idx < p_bytes.len() && (p_bytes[p_idx] == b'?' || p_bytes[p_idx] == s_bytes[s_idx])
            {
                s_idx += 1;
                p_idx += 1;
            } else if p_idx < p_bytes.len() && p_bytes[p_idx] == b'*' {
                star_idx = Some(p_idx);
                s_temp = s_idx;
                p_idx += 1;
            } else if let Some(last_star) = star_idx {
                p_idx = last_star + 1;
                s_temp += 1;
                s_idx = s_temp;
            } else {
                return false;
            }
        }

        while p_idx < p_bytes.len() && p_bytes[p_idx] == b'*' {
            p_idx += 1;
        }

        p_idx == p_bytes.len()
    }
}

#[cfg(test)]
mod tests {
    use super::Solution;

    #[test]
    fn test_example_1() {
        assert!(!Solution::is_match("aa".to_string(), "a".to_string()));
    }

    #[test]
    fn test_example_2() {
        assert!(Solution::is_match("aa".to_string(), "*".to_string()));
    }

    #[test]
    fn test_example_3() {
        assert!(!Solution::is_match("cb".to_string(), "?a".to_string()));
    }

    #[test]
    fn test_empty_strings() {
        assert!(Solution::is_match("".to_string(), "".to_string()));
        assert!(Solution::is_match("".to_string(), "*".to_string()));
        assert!(Solution::is_match("".to_string(), "***".to_string()));
        assert!(!Solution::is_match("".to_string(), "?".to_string()));
        assert!(!Solution::is_match("a".to_string(), "".to_string()));
    }

    #[test]
    fn test_multiple_stars() {
        assert!(Solution::is_match("adceb".to_string(), "*a*b".to_string()));
        assert!(!Solution::is_match(
            "acdcb".to_string(),
            "a*c?b".to_string()
        ));
    }

    #[test]
    fn test_star_at_end() {
        assert!(Solution::is_match("abcdef".to_string(), "abc*".to_string()));
    }
}
